import{f as i,D as s,o as l,c as n,a2 as t,G as d}from"./chunks/framework.n5RLHRfo.js";const k=JSON.parse('{"title":"TextField3D","description":"","frontmatter":{"title":"TextField3D","order":3},"headers":[],"relativePath":"en/extended-objects/text-field/textfield3d.md","filePath":"en/extended-objects/text-field/textfield3d.md","lastUpdated":1792987289000}'),o={name:"en/extended-objects/text-field/textfield3d.md"};function r(h,e,c,p,x,g){const a=s("ExampleFrame");return l(),n("div",null,[e[0]||(e[0]=t('<h1 id="textfield3d" tabindex="-1">TextField3D <a class="header-anchor" href="#textfield3d" aria-label="Permalink to &quot;TextField3D&quot;">​</a></h1><p><strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/TextField3D.html"><code>TextField3D</code></a></strong> is a text object placed at actual coordinates (<code>x, y, z</code>) in 3D space. It is useful for creating signposts in the world, name tags above character heads, or explanatory text attached to specific objects.</p><h2 id="_1-basic-usage" tabindex="-1">1. Basic Usage <a class="header-anchor" href="#_1-basic-usage" aria-label="Permalink to &quot;1. Basic Usage&quot;">​</a></h2><p><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/TextField3D.html"><code>TextField3D</code></a> is treated the same as a general <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/Mesh.html"><code>Mesh</code></a> and is physically located in 3D space.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> textField</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RedGPU.Display.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TextField3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(redGPUContext, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3D World Text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">textField.y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Place in the air</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scene.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addChild</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(textField);</span></span></code></pre></div><h2 id="_2-billboard-and-size-control" tabindex="-1">2. Billboard and Size Control <a class="header-anchor" href="#_2-billboard-and-size-control" aria-label="Permalink to &quot;2. Billboard and Size Control&quot;">​</a></h2><p>3D text can be seen from the side or back depending on the camera position. To make the text always visible from the front, activate the <strong>Billboard</strong> feature, and you can set the world unit size or fixed pixel size as needed.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Property Name</th><th style="text-align:left;">Description</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>useBillboard</code></strong></td><td style="text-align:left;">When activated, the text always faces the front even if the camera rotates.</td><td style="text-align:left;"><code>true</code></td></tr><tr><td style="text-align:left;"><strong><code>worldSize</code></strong></td><td style="text-align:left;">Vertical size in world space (Unit). Horizontal size is automatically adjusted according to text length.</td><td style="text-align:left;"><code>1</code></td></tr><tr><td style="text-align:left;"><strong><code>usePixelSize</code></strong></td><td style="text-align:left;">Whether to use fixed pixel size mode. If <code>true</code>, it is displayed at the rendered physical pixel size regardless of distance.</td><td style="text-align:left;"><code>false</code></td></tr></tbody></table><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1. Set world unit size (shrinks with distance)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">textField.worldSize </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2. Set fixed pixel size (maintains readability regardless of distance)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">textField.usePixelSize </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_3-relationship-between-world-size-and-pixel-size-font" tabindex="-1">3. Relationship between World Size and Pixel Size (Font) <a class="header-anchor" href="#_3-relationship-between-world-size-and-pixel-size-font" aria-label="Permalink to &quot;3. Relationship between World Size and Pixel Size (Font)&quot;">​</a></h2><p>It is important to understand the relationship between the three key properties that determine the size and clarity of text in <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/TextField3D.html"><code>TextField3D</code></a>.</p><h3 id="_3-1-font-size-fontsize" tabindex="-1">3.1 Font Size (<code>fontSize</code>) <a class="header-anchor" href="#_3-1-font-size-fontsize" aria-label="Permalink to &quot;3.1 Font Size (`fontSize`)&quot;">​</a></h3><ul><li><strong>Role</strong>: Determines the <strong>resolution (quality)</strong> when rendering text into a bitmap internally.</li><li><strong>Features</strong>: A larger <code>fontSize</code> produces a larger and clearer source texture. Rather than directly determining the physical size in 3D space, it should be understood as a factor determining the &#39;image quality&#39; of the output.</li></ul><h3 id="_3-2-world-size-worldsize" tabindex="-1">3.2 World Size (<code>worldSize</code>) <a class="header-anchor" href="#_3-2-world-size-worldsize" aria-label="Permalink to &quot;3.2 World Size (`worldSize`)&quot;">​</a></h3><ul><li><strong>Role</strong>: Determines the <strong>physical vertical height</strong> (in Units) within the 3D world space.</li><li><strong>Behavior</strong>: Operates when <code>usePixelSize</code> is <code>false</code>, and the size changes as perspective is applied according to the distance from the camera.</li></ul><h3 id="_3-3-fixed-pixel-mode-usepixelsize" tabindex="-1">3.3 Fixed Pixel Mode (<code>usePixelSize</code>) <a class="header-anchor" href="#_3-3-fixed-pixel-mode-usepixelsize" aria-label="Permalink to &quot;3.3 Fixed Pixel Mode (`usePixelSize`)&quot;">​</a></h3><ul><li><strong>Role</strong>: Placed in 3D space, but displayed on the screen at the <strong>actual rendered pixel size</strong>.</li><li><strong>Relationship with Font</strong>: When this mode is activated, <code>worldSize</code> is ignored, and the actual height of the texture generated by <code>fontSize</code> becomes the output size on the screen. Therefore, it is very useful when constant readability must be maintained regardless of distance, such as for icons or name tags.</li></ul><div class="tip custom-block"><p class="custom-block-title">[Optimization Tip]</p><p>If the text appears too large or small when using <code>usePixelSize</code>, adjust the <code>fontSize</code> instead of the <code>worldSize</code>. Conversely, if it should behave like a general 3D object, it is recommended to set <code>fontSize</code> to an appropriately high value (e.g., 24-48) for texture clarity and adjust the actual size with <code>worldSize</code>.</p></div><h2 id="_4-practical-example-style-and-sizing-mode-comparison" tabindex="-1">4. Practical Example: Style and Sizing Mode Comparison <a class="header-anchor" href="#_4-practical-example-style-and-sizing-mode-comparison" aria-label="Permalink to &quot;4. Practical Example: Style and Sizing Mode Comparison&quot;">​</a></h2><p>Explore various font style options and see the differences between world size (<code>worldSize</code>) mode and fixed pixel (<code>usePixelSize</code>) mode.</p>',20)),d(a,{src:"/RedGPU/examples/3d/textField/textField3D/",style:{width:"100%",height:"500px"}}),e[1]||(e[1]=t('<hr><h2 id="related-examples" tabindex="-1">Related Examples <a class="header-anchor" href="#related-examples" aria-label="Permalink to &quot;Related Examples&quot;">​</a></h2><ul><li><a href="/RedGPU/examples/3d/textField/textField3D/" target="_blank" rel="noopener noreferrer">TextField3D Basics</a></li><li><a href="/RedGPU/examples/3d/textField/textField3DCompare/" target="_blank" rel="noopener noreferrer">TextField3D Sizing Mode Comparison</a></li><li><a href="/RedGPU/examples/3d/interaction/mouseEvent/textField3D/" target="_blank" rel="noopener noreferrer">TextField3D Mouse Events</a></li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Learn about the interaction system to create dynamic content that reacts to user input.</p><ul><li><strong><a href="./../../interaction/">Interaction</a></strong></li></ul>',7))])}const m=i(o,[["render",r]]);export{k as __pageData,m as default};
